To set up relationResolvers in TypeGraphQL with Prisma for your Gardener → Plot relationship:

```typescript
// gardener.ts
import { ObjectType, Field, ID } from "type-graphql";
import { Plot } from "./plot";

@ObjectType()
export class Gardener {
  @Field(() => ID)
  id: string;

  @Field()
  name: string;

  @Field(() => [Plot])
  plots: Plot[];
}

// plot.ts
@ObjectType()
export class Plot {
  @Field(() => ID)
  id: string;

  @Field()
  plantingNotes: string;

  @Field()
  gardenerId: string;
}

// resolver.ts
@Resolver(() => Gardener)
export class GardenerResolver {
  @Query(() => Gardener)
  async gardener(@Arg("id") id: string) {
    return await prisma.gardener.findUnique({ where: { id } });
  }

  @FieldResolver(() => [Plot])
  async plots(@Root() gardener: Gardener) {
    return await prisma.plot.findMany({
      where: { gardenerId: gardener.id }
    });
  }
}
```

The `@FieldResolver` decorator on `plots` tells TypeGraphQL to lazy-load plots when that field is requested. This avoids N+1 queries if you batch DataLoader: wrap the resolver with a dataloader keyed on `gardenerId`.

